(() => {
'use strict';
const DATA=JSON.parse(document.getElementById('course-data').textContent);
const KEY='rn-network-fieldguide.v1';
const $=s=>document.querySelector(s);
const byId=Object.fromEntries(DATA.lessons.map(l=>[l.id,l]));
const questions=Object.fromEntries(DATA.lessons.flatMap(l=>l.questions).map(q=>[q.id,q]));
const sourceById=Object.fromEntries(DATA.sources.map(s=>[s.id,s]));
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plainObject=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const empty=()=>({app:'rn-network-fieldguide',version:1,read:{},answers:{},notes:{},bookmarks:{},labs:{},checklist:{},journal:{},days:[],lastLesson:'mental-model',lastRoute:'home',exam:{bestScore:0},updatedAt:null});
const LABS=[
 {id:'http',icon:'{ }',title:'Inspect the response',desc:'Explore status codes, bodies, and the right next action.',lesson:'http'},
 {id:'retry',icon:'↻',title:'Retry without duplication',desc:'Lose an order reply. Change the key and retry policy.',lesson:'retry'},
 {id:'cache',icon:'◷',title:'The cache time machine',desc:'Change freshness, inactivity, and account scope.',lesson:'query'},
 {id:'auth',icon:'⌁',title:'The refresh stampede',desc:'Expire five requests and log out during refresh.',lesson:'sessions'},
 {id:'outbox',icon:'⇄',title:'Crash the offline queue',desc:'Kill the process at the worst possible point.',lesson:'offline'},
 {id:'trace',icon:'⌇',title:'Read the waterfall',desc:'Find a delay and break the propagation chain.',lesson:'traces'},
 {id:'metrics',icon:'▥',title:'Fix the denominator',desc:'Watch retries change attempt and operation metrics.',lesson:'metrics'},
 {id:'diagnosis',icon:'?',title:'Incident detective',desc:'Use evidence to select a cause and a safe next step.',lesson:'debug'},
];
const labById=Object.fromEntries(LABS.map(l=>[l.id,l]));
function boundedString(x,max=20000){if(typeof x!=='string'||x.length>max)throw Error('A text field has an invalid type or length.');return x;}
function validateProgress(x){
 if(!plainObject(x)||x.app!=='rn-network-fieldguide'||x.version!==1)throw Error('This is not a supported Fieldguide progress backup (version 1).');
 const s=empty();
 for(const field of ['read','bookmarks','labs','checklist']){
  if(x[field]!==undefined&&!plainObject(x[field]))throw Error(`Invalid ${field} records.`);
  const ids=field==='labs'?LABS.map(l=>l.id):field==='checklist'?DATA.checklist.map((_,i)=>String(i)):DATA.lessons.map(l=>l.id);
  for(const id of ids)if(x[field]?.[id]===true)s[field][id]=true;
 }
 if(x.notes!==undefined&&!plainObject(x.notes))throw Error('Invalid notes.');
 for(const l of DATA.lessons)if(x.notes?.[l.id]!==undefined)s.notes[l.id]=boundedString(x.notes[l.id]);
 if(x.answers!==undefined&&!plainObject(x.answers))throw Error('Invalid quiz records.');
 for(const [id,q]of Object.entries(questions)){
  const r=x.answers?.[id];if(r===undefined)continue;
  if(!plainObject(r)||!Number.isInteger(r.choice)||r.choice<0||r.choice>=q.options.length)throw Error('Invalid quiz answer.');
  s.answers[id]={choice:r.choice,correct:r.choice===q.answer,mastered:r.mastered===true||r.choice===q.answer,attempts:Math.min(100000,Math.max(1,Number.isInteger(r.attempts)?r.attempts:1)),wrong:Math.min(100000,Math.max(0,Number.isInteger(r.wrong)?r.wrong:0)),at:typeof r.at==='string'?r.at.slice(0,40):null};
 }
 if(x.journal!==undefined&&!plainObject(x.journal))throw Error('Invalid incident notebook.');
 for(const key of ['symptom','hypotheses','evidence','resolution'])if(x.journal?.[key]!==undefined)s.journal[key]=boundedString(x.journal[key]);
 if(Array.isArray(x.days))s.days=[...new Set(x.days.filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)))].slice(-366);
 if(Object.hasOwn(byId,x.lastLesson))s.lastLesson=x.lastLesson;
 if(typeof x.lastRoute==='string'&&validRoute(x.lastRoute))s.lastRoute=x.lastRoute;
 if(plainObject(x.exam)){
  s.exam.bestScore=Math.min(DATA.exam.length,Math.max(0,Number.isInteger(x.exam.bestScore)?x.exam.bestScore:0));
  if(plainObject(x.exam.responses)&&DATA.exam.every(q=>Number.isInteger(x.exam.responses[q.id])&&x.exam.responses[q.id]>=0&&x.exam.responses[q.id]<q.options.length)){
   s.exam.responses=Object.fromEntries(DATA.exam.map(q=>[q.id,x.exam.responses[q.id]]));
   s.exam.score=DATA.exam.filter(q=>s.exam.responses[q.id]===q.answer).length;
   s.exam.bestScore=Math.max(s.exam.bestScore,s.exam.score);
   s.exam.submittedAt=typeof x.exam.submittedAt==='string'?x.exam.submittedAt.slice(0,40):null;
  }
 }
 s.updatedAt=typeof x.updatedAt==='string'?x.updatedAt.slice(0,40):null;
 return s;
}
function validRoute(r){if(typeof r!=='string')return false;const parts=r.split('/');if(parts.length>2)return false;const [v,id]=parts;return (['home','review','notes','sources','glossary','exam'].includes(v)&&parts.length===1)||(v==='lesson'&&Object.hasOwn(byId,id))||(v==='labs'&&(parts.length===1||Object.hasOwn(labById,id)));}
let state=empty(),storageOkay=true,storageLocked=false,storageReason='',pendingImport=null,recoveryRaw=null;
try{const raw=localStorage.getItem(KEY);if(raw){recoveryRaw=raw;state=validateProgress(JSON.parse(raw));recoveryRaw=null;}localStorage.setItem(KEY+'.probe','1');localStorage.removeItem(KEY+'.probe');}
catch(error){storageOkay=false;storageReason=error.message;if(error.name!=='SecurityError'&&error.name!=='QuotaExceededError'){storageLocked=true;storageReason='The saved record could not be read. Existing data is preserved; export or reset in Field notes.';}}
let route=location.hash.slice(1);if(!validRoute(route))route=state.lastRoute;
const ui={search:'',sourceSearch:'',glossarySearch:'',drafts:new Map(),examDrafts:{},reviewTab:'mistakes',flashIndex:0,flipped:false,labConfig:{},labRuns:{},diagnosis:{},confirmReset:false};
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function touch(){const d=today();if(!state.days.includes(d))state.days=[...state.days,d].slice(-366);}
function save(){touch();state.updatedAt=new Date().toISOString();if(!storageLocked){try{localStorage.setItem(KEY,JSON.stringify(state));storageOkay=true;storageReason='';}catch(e){storageOkay=false;storageReason='Browser storage is unavailable or full. Export a progress backup to keep this session.';}}updateSave();}
function updateSave(){const s=$('#save-state');if(s){s.innerHTML=`<span class="dot" style="${storageOkay?'':'background:var(--warning,#b97f40)'}"></span>${storageOkay?'Saved on this browser':'Session only · export backup'}`;s.title=storageOkay?'Notes, quizzes, and progress are saved locally. No account or server.':storageReason;}const p=$('#header-progress');if(p)p.textContent=`${completed().length}/28 chapters complete`;}
function completed(){return DATA.lessons.filter(l=>state.read[l.id]&&l.questions.every(q=>state.answers[q.id]?.mastered));}
function learned(l){return l.questions.filter(q=>state.answers[q.id]?.mastered).length;}
function done(l){return !!state.read[l.id]&&learned(l)===l.questions.length;}
function nav(r){if(!validRoute(r))r='home';if(location.hash.slice(1)===r){route=r;render();}else location.hash=r;}
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);route=validRoute(r)?r:'home';state.lastRoute=route;if(route.startsWith('lesson/'))state.lastLesson=route.split('/')[1];save();render();window.scrollTo({top:0,behavior:'instant'});$('#main-content')?.focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validateProgress(JSON.parse(e.newValue));render();toast('Progress updated from another tab.');}catch{toast('Another tab saved an unreadable record.');}}});
let toastTimer;function toast(msg){const t=$('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',4200);}
function inline(s){return escape(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
function markdown(text){
 const lines=text.split('\n');let out='',i=0;
 while(i<lines.length){let line=lines[i].trim();if(!line){i++;continue;}
  if(line.startsWith('```')){const lang=line.slice(3),buf=[];i++;while(i<lines.length&&!lines[i].trim().startsWith('```'))buf.push(lines[i++]);i++;out+=`<div class="code-wrap"><span class="code-lang">${escape(lang||'reference')}</span><button class="copy" data-action="copy-code">Copy</button><pre><code>${escape(buf.join('\n'))}</code></pre></div>`;continue;}
  if(line.startsWith('## ')){out+=`<h2>${inline(line.slice(3))}</h2>`;i++;continue;}
  if(/^(- |\d+\. )/.test(line)){const ordered=/^\d/.test(line);out+=ordered?'<ol>':'<ul>';while(i<lines.length&&/^(?:- |\d+\. )/.test(lines[i].trim())){out+=`<li>${inline(lines[i].trim().replace(/^(?:- |\d+\. )/,''))}</li>`;i++;}out+=ordered?'</ol>':'</ul>';continue;}
  const buf=[line];i++;while(i<lines.length&&lines[i].trim()&&!/^(## |```|- |\d+\. )/.test(lines[i].trim()))buf.push(lines[i++].trim());out+=`<p>${inline(buf.join(' '))}</p>`;
 }
 return out;
}
function btn(label,action,extra='',cls=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function linkBtn(label,r,cls=''){return btn(label,'nav',`data-route="${r}"`,cls);}
function statusIcon(l){return `<span aria-label="${done(l)?'Complete':state.read[l.id]?'Studied, quiz pending':'Not yet studied'}" class="status-circle ${done(l)?'done':state.read[l.id]?'partial':''}">${done(l)?'✓':state.read[l.id]?'·':''}</span>`;}
function sourceLinks(ids){return ids.map(id=>{const s=sourceById[id];return s?`<a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)}</a>`:'';}).join(' · ');}
function header(){const active=route.split('/')[0];return `<header><div class="topline"><div class="brand"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="5" cy="6" r="2.5"/><circle cx="19" cy="6" r="2.5"/><circle cx="12" cy="18" r="2.5"/><path d="M7.5 6h9M6.3 8l4.5 7.5M17.7 8l-4.5 7.5"/></svg></span> The network fieldguide</div><div class="save-indicator" id="save-state"></div></div><nav class="tabs" aria-label="Course sections">${[['home','Course'],['lesson','Learn'],['labs','Labs'],['review','Review'],['notes','Field notes'],['sources','Sources']].map(([r,label])=>linkBtn(label,r==='lesson'?`lesson/${state.lastLesson}`:r,active===r?'active':'').replace('<button ',`<button ${active===r?'aria-current="page" ':''}`)).join('')}</nav></header>`;}
function shell(page){return header()+`<main id="main-content" tabindex="-1">${!storageOkay?`<div class="notice">${escape(storageReason||'Local browser storage is blocked in this frame. Your work is kept for this session. Save an export from Field notes, or use the downloaded HTML at a stable browser address.')}</div>`:''}${page}</main><footer class="footer"><span>React Native networking · researched ${DATA.updated}</span><span id="header-progress">${completed().length}/28 chapters complete</span></footer>`;}
function overviewResults(){const term=ui.search.toLowerCase();const filtered=DATA.lessons.filter(l=>(l.title+' '+l.subtitle+' '+l.body).toLowerCase().includes(term));if(!filtered.length)return '<div class="empty">No chapters match. Try “token”, “TLS”, “offline”, or “trace”.</div>';return DATA.stages.map((s,stage)=>{const lessons=filtered.filter(l=>l.stage===stage);if(!lessons.length)return '';const all=DATA.lessons.filter(l=>l.stage===stage);return `<details class="stage" style="--stage-color:${s.color}" ${term||stage===0?'open':''}><summary><span class="stage-num">0${stage+1}</span><span class="stage-title"><strong>${s.name}</strong><small>${s.description}</small></span><span class="stage-count">${all.filter(done).length}/${all.length} complete ＋</span></summary>${lessons.map(l=>`<button class="lesson-row" data-action="nav" data-route="lesson/${l.id}"><span class="lesson-index">${String(DATA.lessons.indexOf(l)+1).padStart(2,'0')}</span><span class="row-content"><span class="title">${escape(l.title)}</span><small>${escape(l.subtitle)} · ${l.minutes} min + practice</small></span>${statusIcon(l)}</button>`).join('')}</details>`;}).join('');}
function home(){const count=completed().length;return `<section class="hero"><div class="eyebrow"><span class="dot"></span>A practical course / React Native + TypeScript</div><h1>From a request<br>to a reliable app.</h1><p class="lead">Understand the journey. Build for failure. See the whole system. A beginner-friendly path through production mobile networking, one concrete idea at a time.</p><div class="actions">${linkBtn(count||state.read[state.lastLesson]?'Continue learning →':'Start with the first request →',`lesson/${state.lastLesson}`,'primary')}${linkBtn('Explore the labs','labs','ghost')}${btn('Save course HTML','download-course','', 'ghost')}</div><p class="micro">No account. No dependencies. No tracking. Lessons, quizzes, notes, and progress work offline.</p><div class="stats"><div class="stat"><strong>28</strong><span>guided chapters</span></div><div class="stat"><strong>100</strong><span>quiz + exam questions</span></div><div class="stat"><strong>8</strong><span>interactive labs</span></div><div class="stat"><strong>${count}<span style="display:inline;font-size:1rem"> / 28</span></strong><span>chapters completed</span></div></div><div class="progress-track" role="progressbar" aria-label="Chapters complete" aria-valuemin="0" aria-valuemax="28" aria-valuenow="${count}"><span style="width:${count/28*100}%"></span></div><div class="progress-caption"><span>${count===28?'Every chapter studied and its quiz answered correctly.':'Complete a chapter by marking it studied and answering all 3 quiz questions correctly.'}</span><span>${Math.round(count/28*100)}%</span></div></section><div class="journey" aria-label="The request journey">${[['01','The tap','intent & UI'],['02','The phone','cache & radio'],['03','The wire','DNS · TLS · HTTP'],['04','The API','identity & rules'],['05','The data','durable effects'],['06','The evidence','logs & traces']].map(([n,t,d])=>`<div class="node"><div class="node-icon">${n}</div><strong>${t}</strong><small>${d}</small></div>`).join('')}</div><div class="two-col"><div class="panel soft"><div class="eyebrow">Your running example</div><h3>Meet Fieldcart.</h3><p class="muted" style="font-size:.87rem">A shop app with search, sign-in, carts, orders, photo uploads, and live delivery updates. You’ll learn what happens when its phone goes offline halfway through checkout.</p></div><div class="panel"><div class="eyebrow">How to use the course</div><p style="font-size:.87rem">Read → predict → try a lab → answer the quiz → keep evidence. Allow roughly <strong>20–30 hours with exercises</strong>; pace is personal. No React Native app is installed or built by these browser simulations.</p>${linkBtn('Open the glossary →','glossary','small ghost')}</div></div><div class="section-heading"><h2>Your learning path</h2><small>6 stages · open in any order</small></div><label for="course-search" class="note-label">Find a chapter or concept</label><input class="searchbox" id="course-search" type="search" placeholder="Try: offline, retries, authentication, tracing…" value="${escape(ui.search)}"><div id="course-results">${overviewResults()}</div><div class="panel soft"><h3>A foundation you can put to work.</h3><p style="font-size:.85rem">The course distinguishes client behavior from guarantees your API must provide. Labs use deterministic models, not a live network. Source links open official documentation; revisit version-specific guidance before shipping.</p><div class="actions compact">${linkBtn('See the research','sources','small ghost')}${linkBtn('Production checklist','notes','small ghost')}</div></div>`;}
function questionHTML(q,mode='lesson'){
 const exam=mode==='exam';const r=exam?(state.exam.responses?{choice:state.exam.responses[q.id],correct:state.exam.responses[q.id]===q.answer}:null):state.answers[q.id];
 const draft=exam?ui.examDrafts[q.id]:ui.drafts.get(q.id);const graded=!!r&&(exam||!ui.drafts.has(q.id));const choice=graded?r.choice:draft;
 return `<section class="q-card" id="${q.id}" data-question="${q.id}"><div class="q-number">${exam?'Assessment':'Knowledge check'} · ${q.id.replace('q','')}</div><h3>${escape(q.prompt)}</h3><div class="options" role="group" aria-label="${escape(q.prompt)}">${q.options.map((o,i)=>`<button class="option ${choice===i?'selected ':''}${graded&&i===q.answer?'correct ':''}${graded&&choice===i&&!r.correct?'incorrect':''}" data-action="${exam?'exam-choice':'choice'}" data-q="${q.id}" data-choice="${i}" aria-pressed="${choice===i}" ${graded?'disabled':''}><span class="option-letter">${graded&&i===q.answer?'✓':String.fromCharCode(65+i)}</span><span>${escape(o)}</span></button>`).join('')}</div>${graded?`<div class="feedback ${r.correct?'good':'bad'}"><strong>${r.correct?'Correct.':'Let’s unpack this.'}</strong> ${escape(q.why)}</div>`:''}${!exam?`<div class="q-footer">${graded?btn(r.correct?'Practice again':'Try again','retry-q',`data-q="${q.id}"`,'small ghost'):btn('Check answer','check-q',`data-q="${q.id}" ${Number.isInteger(choice)&&choice>=0?'':'disabled'}`,'small primary')}<small>${r?`${r.attempts} attempt${r.attempts===1?'':'s'}${r.mastered?' · answered correctly at least once':''}`:'Choose an answer, then check your reasoning.'}</small></div>`:''}</section>`;
}
function lesson(id){const l=byId[id]||DATA.lessons[0],i=DATA.lessons.indexOf(l);state.lastLesson=l.id;return `<select class="chapter-select" aria-label="Choose a chapter" id="chapter-picker">${DATA.lessons.map((x,n)=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${String(n+1).padStart(2,'0')} · ${escape(x.title)}</option>`).join('')}</select><div class="learning-layout"><aside class="lesson-nav-list" aria-label="Chapter navigation">${DATA.stages.map((s,n)=>`<small>0${n+1} · ${s.short}</small>${DATA.lessons.filter(x=>x.stage===n).map(x=>`<button class="${x.id===l.id?'active':''}" ${x.id===l.id?'aria-current="page"':''} data-action="nav" data-route="lesson/${x.id}">${statusIcon(x)}<span>${escape(x.title)}</span></button>`).join('')}`).join('')}</aside><article class="lesson-content"><header class="chapter-head"><div class="eyebrow">Stage 0${l.stage+1} · Chapter ${String(i+1).padStart(2,'0')} / 28</div><h1>${escape(l.title)}</h1><p class="subtitle">${escape(l.subtitle)}</p><div class="pill-row"><span class="chip">${l.minutes} min + practice</span><span class="chip">${learned(l)}/3 quiz concepts checked</span>${done(l)?'<span class="badge">✓ Chapter complete</span>':''}${btn(state.bookmarks[l.id]?'★ Bookmarked':'☆ Bookmark','bookmark',`data-id="${l.id}" aria-pressed="${!!state.bookmarks[l.id]}"`,'small ghost')}</div></header><div class="objectives"><strong>By the end, you can</strong><ul>${l.objectives.map(x=>`<li>${escape(x)}</li>`).join('')}</ul></div><div class="lesson-text">${markdown(l.body)}</div><section class="panel practice"><div class="eyebrow">Put it into practice</div><p>${escape(l.exercise)}</p>${l.lab?linkBtn('Open the related lab →',`labs/${l.lab}`,'small primary'):''}</section><div class="actions">${btn(state.read[l.id]?'✓ Marked as studied':'Mark this chapter as studied','read',`data-id="${l.id}" aria-pressed="${!!state.read[l.id]}"`,'primary')}<span class="micro">${state.read[l.id]?'Quiz answers complete the chapter.':'Mark after reading and considering the exercise.'}</span></div><div class="section-heading"><h2>Check your understanding</h2><small>3 questions · explanations included</small></div>${l.questions.map(q=>questionHTML(q)).join('')}<section class="panel"><label class="note-label" for="lesson-note">Your field notes for this chapter</label><textarea id="lesson-note" data-note="${l.id}" maxlength="20000" placeholder="What surprised you? What will you verify in your app?">${escape(state.notes[l.id]||'')}</textarea><small>Saved locally as you type. Don’t put real credentials or personal customer data here.</small></section><details class="panel"><summary>Primary references for this chapter</summary><p style="margin-top:14px;font-size:.8rem">${sourceLinks(l.sources)}</p><small>Read with your installed versions in mind. Research snapshot: ${DATA.updated}.</small></details><nav class="chapter-nav" aria-label="Previous and next chapter">${i?linkBtn('← '+DATA.lessons[i-1].title,`lesson/${DATA.lessons[i-1].id}`,'ghost'):'<span></span>'}${i<27?linkBtn(DATA.lessons[i+1].title+' →',`lesson/${DATA.lessons[i+1].id}`,'primary'):linkBtn('Open final assessment →','exam','primary')}</nav></article></div>`;}
function review(){const mistakes=DATA.lessons.flatMap(l=>l.questions.map(q=>({l,q}))).filter(({q})=>state.answers[q.id]&&!state.answers[q.id].correct);const bookmarks=DATA.lessons.filter(l=>state.bookmarks[l.id]);const concepts=Object.entries(DATA.glossary);const card=concepts[ui.flashIndex%concepts.length];return `<div class="chapter-head"><div class="eyebrow">Recall / explain / apply</div><h1>Make it stick.</h1><p class="subtitle">Revisit mistakes, keep useful chapters close, and explain concepts in your own words.</p></div><div class="two-col"><div class="panel soft"><h3>${Object.values(state.answers).filter(a=>a.mastered).length} / 84 concepts checked</h3><p class="muted" style="font-size:.85rem">${mistakes.length?`${mistakes.length} question${mistakes.length===1?' needs':'s need'} another look.`:'No unresolved quiz mistakes. Unanswered questions are still waiting in the chapters.'}</p></div><div class="panel"><h3>Final assessment</h3><p class="muted" style="font-size:.85rem">16 fresh scenarios. Target 13/16. ${state.exam.bestScore?`Your best: ${state.exam.bestScore}/16.`:'This is a knowledge checkpoint, not a certification.'}</p>${linkBtn('Take the assessment →','exam','small primary')}</div></div><div class="section-heading"><h2>Flashcards</h2><small>${ui.flashIndex%concepts.length+1} / ${concepts.length} concepts</small></div><div class="panel flashcard"><div class="eyebrow">Explain this before revealing</div><h3>${escape(card[0])}</h3>${ui.flipped?`<p>${escape(card[1])}</p>`:'<p class="muted">Say what it means, then give an example from Fieldcart.</p>'}<div class="actions compact">${btn(ui.flipped?'Hide definition':'Reveal definition','flip-card','','small primary')}${btn('Next concept →','next-card','','small ghost')}</div></div><div class="section-heading"><h2>Unresolved mistakes</h2><small>Retry here or return to the chapter</small></div>${mistakes.length?mistakes.map(({l,q})=>`<div class="source-links">${linkBtn('Revisit: '+escape(l.title),`lesson/${l.id}`,'small ghost')}</div>${questionHTML(q)}`).join(''):'<div class="panel"><p>No unresolved mistakes yet. Complete a chapter quiz to build your review queue.</p></div>'}<div class="section-heading"><h2>Bookmarked chapters</h2><small>${bookmarks.length} saved</small></div>${bookmarks.length?bookmarks.map(l=>`<button class="lesson-row" data-action="nav" data-route="lesson/${l.id}"><span class="row-content"><span class="title">${escape(l.title)}</span><small>${escape(l.subtitle)}</small></span>${statusIcon(l)}</button>`).join(''):'<p class="muted">Use ☆ Bookmark inside a chapter.</p>'}<div class="actions">${linkBtn('Browse all 55 glossary terms →','glossary','ghost')}</div>`;}
function exam(){const submitted=!!state.exam.responses;const score=state.exam.score;return `<div class="chapter-head"><div class="eyebrow">Final knowledge checkpoint</div><h1>Reason through the failures.</h1><p class="subtitle">16 scenarios · answer every question before checking · target 13/16.</p></div><div class="callout">Use this to find gaps in your understanding. Your answers are saved when you submit; unfinished selections in this assessment stay only in this open session. Chapter quizzes save each checked answer.</div>${submitted?`<div class="result-banner"><h3>${score}/16 · ${score>=13?'Checkpoint passed':'Keep practicing'}</h3><p>${score>=13?'Take the same reasoning into your capstone and real-device failure drills.':'Read the explanations below and revisit the relevant chapters.'} Best score: ${state.exam.bestScore}/16.</p>${btn('Retake the assessment','retake-exam','','small ghost')}</div>`:''}${DATA.exam.map(q=>questionHTML(q,'exam')).join('')}<div class="actions">${submitted?linkBtn('Open the production checklist →','notes','primary'):btn('Check all 16 answers','submit-exam',`${DATA.exam.every(q=>Number.isInteger(ui.examDrafts[q.id]))?'':'disabled'}`,'primary')}${linkBtn('Back to review','review','ghost')}</div>`;}
function glossaryResults(){const term=ui.glossarySearch.toLowerCase();const entries=Object.entries(DATA.glossary).filter(([k,v])=>(k+' '+v).toLowerCase().includes(term));return entries.length?`<dl>${entries.map(([k,v])=>`<div class="definition"><dt>${escape(k)}</dt><dd>${escape(v)}</dd></div>`).join('')}</dl>`:'<p class="empty">No matching concepts.</p>';}
function glossary(){return `<div class="chapter-head"><div class="eyebrow">Plain-language reference</div><h1>A working vocabulary.</h1><p class="subtitle">55 terms, explained without assuming you already know the jargon.</p></div><label for="glossary-search" class="note-label">Find a concept</label><input id="glossary-search" class="searchbox" type="search" value="${escape(ui.glossarySearch)}" placeholder="Search terms or definitions…"><div id="glossary-results">${glossaryResults()}</div>`;}
function sourcesResults(){const term=ui.sourceSearch.toLowerCase();return DATA.sources.filter(s=>s.usable&&(s.title+' '+s.url).toLowerCase().includes(term)).map(s=>`<div class="source"><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a><p>Official primary reference · retrieved ${s.retrieved} · ${s.id}</p></div>`).join('')||'<p class="empty">No matching references.</p>';}
function sources(){const usable=DATA.sources.filter(s=>s.usable);return `<div class="chapter-head"><div class="eyebrow">Research / provenance / limitations</div><h1>Built on primary sources.</h1><p class="subtitle">${usable.length} readable official references, retrieved ${DATA.updated}. Each chapter links the sources behind it.</p></div><div class="panel soft"><h3>How the research was done</h3><p style="font-size:.87rem">Read official React Native, React, Apple, Android, Expo, TanStack Query, MSW, OpenTelemetry, Sentry, GraphQL, MDN, and HTTP/OAuth/W3C specifications. Readable snapshots and the access manifest are retained in the project folder; this HTML includes their source links.</p><p style="font-size:.87rem">The lessons are an authored synthesis. Timings, SLO targets, app scenarios, and lab numbers are teaching examples. Simulations do not test your actual API, native runtime, or monitoring deployment.</p></div><div class="panel"><h3>Version-sensitive findings</h3><ul style="font-size:.85rem"><li>React Native DevTools’ Network/Performance panels are documented from 0.83; coverage differs by transport and Expo integration.</li><li>The retrieved current MSW native guide uses <code>@msw/react-native</code>; older <code>msw/native</code> examples are obsolete.</li><li>TanStack Query examples target v5; defaults and persistence options should be checked against the installed version.</li><li>React Native support is not implied by OpenTelemetry’s Node/browser JavaScript documentation.</li><li>W3C Trace Context and Sentry’s documented propagation headers need a compatible integration; they are not interchangeable by name.</li><li>Background schedules and native transfer support depend on OS, target SDK, framework version, and build configuration.</li></ul></div><label class="note-label" for="source-search">Filter primary references</label><input class="searchbox" type="search" id="source-search" value="${escape(ui.sourceSearch)}" placeholder="React Native, OAuth, tracing, caching…"><div class="source-list" id="source-results">${sourcesResults()}</div><details class="panel"><summary>Access limitations and superseded retrievals</summary><ul style="font-size:.8rem">${DATA.sources.filter(s=>!s.usable).map(s=>`<li>${escape(s.title)}: ${s.ok?'returned a JavaScript shell; the corresponding Markdown article was retrieved and used instead.':escape(s.error||'not retrieved')+'. Not used as evidence.'}</li>`).join('')}</ul><p class="micro">Documentation can change after this snapshot. Recheck compatibility, security guidance, and store/platform policy before shipping. This course does not replace product-specific security, compliance, or native integration review.</p></details>`;}
function notes(){const checkCount=Object.values(state.checklist).filter(Boolean).length;const withNotes=DATA.lessons.filter(l=>state.notes[l.id]?.trim());return `<div class="chapter-head"><div class="eyebrow">Your evidence / your next app</div><h1>Keep a field notebook.</h1><p class="subtitle">Save what you learned, what you observed, and what you still need to prove.</p></div>${storageLocked&&recoveryRaw!==null?`<div class="panel"><h3>Preserve the unreadable saved record</h3><p style="font-size:.85rem">Automatic writes are paused so your original data remains untouched. Download its exact contents before resetting or replacing it with an imported backup.</p>${btn('Download original saved record','export-recovery','','small primary')}</div>`:''}<div class="panel soft"><h3>Your progress stays here.</h3><p style="font-size:.87rem">Progress lives in this browser’s local storage for this file or origin. It is not synced across devices or tabs with different origins. Private browsing, storage clearing, moving files, or an embedded frame’s storage policy can remove or isolate it. Export regularly; use the saved HTML at a stable address for dependable continuity.</p><div class="actions compact">${btn('Export progress JSON','export','','small primary')}${btn('Import a backup','import','','small ghost')}${btn('Save course HTML','download-course','','small ghost')}${btn('Download field notes','export-notes','','small ghost')}</div><small>The course HTML contains the curriculum. The separate JSON backup contains your progress and notes. Import replaces the current local record after you confirm the preview.</small></div>${pendingImport?`<section class="import-confirm"><h3>Review this backup</h3><p>${pendingImport.read?Object.values(pendingImport.read).filter(Boolean).length:0} studied chapters · ${Object.keys(pendingImport.notes).length} note entries · ${Object.keys(pendingImport.answers).length} checked answers. Imported text is treated as plain text.</p><div class="actions compact">${btn('Replace current progress','confirm-import','','small primary')}${btn('Cancel import','cancel-import','','small ghost')}</div></section>`:''}<div class="section-heading"><h2>Production evidence checklist</h2><small id="check-count">${checkCount}/${DATA.checklist.length} verified</small></div><p class="muted" style="font-size:.85rem">Tick only after verifying the behavior in your own app. These are self-recorded evidence items, separate from course completion.</p><div class="checklist">${DATA.checklist.map(([label,text],i)=>`<label><input type="checkbox" data-check="${i}" ${state.checklist[i]?'checked':''}><span><strong>${escape(label)}</strong>${escape(text)}</span></label>`).join('')}</div><div class="section-heading"><h2>Incident notebook</h2><small>Separate facts from hypotheses</small></div><div class="notes-grid">${[['symptom','1. Symptom and impact','What did users see? Which build, device, network, and time window?'],['hypotheses','2. Hypotheses and disconfirming tests','For each possible cause, what observation would prove it wrong?'],['evidence','3. Observations and evidence','Sanitized request/trace IDs, timing boundaries, reproducible steps, and facts.'],['resolution','4. Mitigation, cause, and follow-up','What restored outcomes? What evidence supports the cause? Who owns each prevention step?']].map(([key,label,placeholder])=>`<section><label for="journal-${key}" class="note-label">${label}</label><textarea id="journal-${key}" data-journal="${key}" maxlength="20000" placeholder="${placeholder}">${escape(state.journal[key]||'')}</textarea></section>`).join('')}</div><div class="section-heading"><h2>Chapter notes</h2><small>${withNotes.length} entries</small></div>${withNotes.length?withNotes.map(l=>`<details class="panel"><summary>${escape(l.title)}</summary><p style="white-space:pre-wrap;margin-top:16px;font-size:.85rem">${escape(state.notes[l.id])}</p>${linkBtn('Edit in chapter →',`lesson/${l.id}`,'small ghost')}</details>`).join(''):'<p class="muted">Each chapter has a notes box. Your entries will appear here.</p>'}<details class="panel"><summary>Reset local course data</summary><p style="margin-top:14px;font-size:.85rem">This removes this course’s progress, notes, lab badges, assessment, and checklist from this browser. Export first if you want a copy.</p>${ui.confirmReset?`<div class="actions">${btn('Delete this course’s local progress','confirm-reset','','small danger')}${btn('Keep my data','cancel-reset','','small ghost')}</div>`:btn('Review reset…','reset','','small danger')}</details>`;}
const defaults={
 http:{status:'202',action:'render'},
 retry:{attempts:3,stable:false,dedupe:false,jitter:true,budget:5000},
 cache:{age:60,stale:30,inactive:20,gc:120,switchAccount:false,scope:true},
 auth:{calls:5,single:false,logout:false,guard:false},
 outbox:{crash:'server',atomic:true,stable:false,dedupe:false,switchAccount:false,bound:false},
 trace:{scenario:'a',propagate:true,sampled:true,cause:'unknown'},
 metrics:{fail:20,recover:75,denominator:'attempts'},
 diagnosis:{case:'0',cause:'',step:''},
};
const HTTP_CASES={
 '200':{name:'OK',body:'{"items":[{"id":"p_1","name":"Notebook"}]}',action:'render',explain:'Validate the JSON at runtime, then use the result. HTTP success alone does not establish the expected schema.'},
 '202':{name:'Accepted',body:'{"operationId":"op_42","status":"processing"}',action:'pending',explain:'Work is accepted, not completed. Follow the documented operation-status contract and show processing.'},
 '204':{name:'No Content',body:'(no content)',action:'empty',explain:'Do not call json() on this empty response. Your domain wrapper decides whether the lack of data is expected.'},
 '401':{name:'Unauthorized',body:'{"code":"access_token_expired"}',action:'refresh',explain:'For this documented expired-token code, join a bounded single-flight refresh for the current session. Not every auth error is a refresh opportunity.'},
 '403':{name:'Forbidden',body:'{"code":"order_access_denied"}',action:'forbidden',explain:'The server denied permission. Repeating token refresh is not a general remedy; show a safe permission message.'},
 '409':{name:'Conflict',body:'{"code":"cart_version_conflict"}',action:'conflict',explain:'Fetch the current version and follow your domain conflict strategy. A blind stale-write retry can repeat forever.'},
 '429':{name:'Too Many Requests',body:'Retry-After: 30\n\n{"code":"rate_limited"}',action:'wait',explain:'Respect the documented minimum wait. If 30 seconds does not fit the operation budget, defer or fail clearly rather than retrying early.'},
 '503':{name:'Service Unavailable',body:'{"code":"temporarily_unavailable"}',action:'retry',explain:'For this modeled safe read, a bounded retry with backoff may help. Do not generalize it to an ambiguous non-idempotent write.'},
};
const DIAGNOSES=[
 {title:'Only the Android release build fails',evidence:['Debug connects through a development proxy.','Release fails before an HTTP status exists.','Logcat reports certificate trust validation failure.','The API logs no corresponding request.'],causes:['CORS headers are missing','A native TLS trust/configuration difference','A malformed JSON body'],correctCause:1,steps:['Disable certificate validation in release','Compare the release trust config and certificate chain; keep fixes scoped','Retry five times without checking native logs'],correctStep:1,why:'The evidence points to native trust before HTTP. Inspect chain, hostname, time, and release/debug trust settings; browser CORS is unrelated.'},
 {title:'HTTP 200, but the screen says nothing loaded',evidence:['The response body is HTML from an upstream error page.','The app expects a JSON product array.','A catch block returns an empty array.','Users see “No products yet.”'],causes:['A decode/contract error hidden as an empty result','A proven successful empty catalog','An authentication refresh storm'],correctCause:0,steps:['Keep returning [] for all errors','Validate the response and preserve a typed failure with a truthful UI','Add a second query cache with the same key'],correctStep:1,why:'Transport success is not schema success. Fix the error boundary and upstream contract; preserve a safe diagnostic category rather than lying with an empty state.'},
 {title:'Two orders after a weak-signal checkout',evidence:['The first order committed before its reply was lost.','The retry generated a new idempotency key.','The server stores one result per key.','Two records exist with different keys.'],causes:['A failed deduplication identity across retries','Strict Mode definitely created the orders','An image cache issue'],correctCause:0,steps:['Create a new key on every timeout','Persist one key per logical operation and reconcile the known outcomes','Hide one order locally without checking the server'],correctStep:1,why:'Changing the key makes the duplicate look like a new operation. Repair identity generation and server/client recovery, then handle the existing duplicate through the business process.'},
 {title:'The catalog takes 3 seconds, but the API takes 80 ms',evidence:['One HTTP attempt completes in 150 ms including body reading.','A measured synchronous transformation consumes 2.4 seconds.','The JS thread stalls during that transformation.','The list renders after the transformation finishes.'],causes:['A confirmed DNS delay','Client processing dominates the measured delay','A guaranteed database bottleneck'],correctCause:1,steps:['Increase the API timeout','Reduce/optimize measured client work and remeasure release-device behavior','Add retries to speed up rendering'],correctStep:1,why:'The timer boundaries isolate the main delay after transfer. Optimize the verified transformation and payload rather than diagnosing DNS from a screen timer.'},
 {title:'The mobile trace ends at the API boundary',evidence:['App sends sentry-trace and baggage.','API is configured only for unrelated W3C context extraction.','API requests appear in a separate trace.','The server did process the call.'],causes:['The request never reached the server','A propagation-format/integration mismatch','An automatic order rollback'],correctCause:1,steps:['Assume any tracing header works with every backend','Configure a compatible documented propagation path and verify parentage','Put the user’s password in baggage for correlation'],correctStep:1,why:'Both sides emit spans, but incompatible context handling disconnects them. Use supported integration and verify a shared causal trace, without sensitive baggage.'},
];
function config(id){return ui.labConfig[id]||(ui.labConfig[id]={...defaults[id]});}
function selectControl(id,key,label,options){const c=config(id);return `<label class="control"><span>${label}</span><select data-lab="${id}" data-field="${key}">${options.map(([value,text])=>`<option value="${escape(value)}" ${String(c[key])===String(value)?'selected':''}>${escape(text)}</option>`).join('')}</select></label>`;}
function rangeControl(id,key,label,min,max,step=1,unit=''){const c=config(id);return `<label class="control"><span>${label}<strong>${c[key]}${unit}</strong></span><input aria-label="${escape(label)}" type="range" min="${min}" max="${max}" step="${step}" value="${c[key]}" data-lab="${id}" data-field="${key}"></label>`;}
function checkControl(id,key,label){return `<label class="control check"><input type="checkbox" data-lab="${id}" data-field="${key}" ${config(id)[key]?'checked':''}><span>${label}</span></label>`;}
function readouts(items){return `<div class="readout">${items.map(([n,t])=>`<div><strong>${escape(n)}</strong><small>${escape(t)}</small></div>`).join('')}</div>`;}
function events(items){return `<ol class="event-list">${items.map(item=>{const [text,type]=Array.isArray(item)?item:[item,''];return `<li class="${type}">${escape(text)}</li>`;}).join('')}</ol>`;}
function markLab(id,condition){if(condition&&!state.labs[id]){state.labs[id]=true;save();toast('Lab challenge completed. Badge saved locally.');}}
function simRetry(c){
 let attempts=1,orders=1,elapsed=800;
 const timeline=['0 ms · send operation op_42 with key k_42.','100 ms · server commits an order; its reply is lost.','800 ms · client deadline expires; the outcome is unknown.'];
 if(c.attempts<2)timeline.push('No recovery attempt is allowed. Order exists, but the client still needs reconciliation.');
 else{
  const wait=c.jitter?180:0;
  if(elapsed+wait+300>c.budget)timeline.push('Remaining operation budget is too small for the modeled recovery attempt. Stop and reconcile later.');
  else{elapsed+=wait+300;attempts++;if(!(c.stable&&c.dedupe))orders++;timeline.push(`${800+wait} ms · retry with ${c.stable?'the original key k_42':'a new key k_99'}.`);timeline.push(c.stable&&c.dedupe?'Server recognizes the same operation and returns its recorded outcome.':'The retry produces a second order in this model.');}
 }
 return {attempts,orders,elapsed,timeline,recovered:attempts===2,safe:attempts===2&&orders===1};
}
function simCache(c){const inactive=Math.min(c.inactive,c.age),present=inactive<c.gc;const identityMatch=!c.switchAccount||!c.scope;const usable=present&&identityMatch;const stale=c.age>=c.stale;return {inactive,present,usable,stale,leak:usable&&c.switchAccount&&!c.scope,fetch:!usable||stale};}
function simAuth(c){return {refreshes:c.single?1:c.calls,rejections:c.single?0:c.calls-1,resurrected:c.logout&&!c.guard,acceptedAfterLogout:c.logout&&!c.guard,active:!c.logout||!c.guard};}
function simOutbox(c){
 if(c.crash==='local'&&!c.atomic)return {local:true,queued:false,orders:0,status:'Local change persisted, synchronization intent missing',safe:false,events:['The local row was saved.','Process died before a separate outbox insert.','After restart there is no row to tell the sync worker what to send.']};
 if(c.crash==='local'&&c.atomic)return {local:false,queued:false,orders:0,status:'Transaction rolled back; no half-saved draft',safe:true,events:['Crash occurs before the atomic local/outbox transaction commits.','Neither record becomes durable. The UI must not have promised durable save before commit.','The original unsaved edit requires the defined draft recovery policy.']};
 if(c.switchAccount&&c.bound)return {local:true,queued:true,orders:1,status:'Paused: pending work belongs to the old account',safe:true,events:['The original account’s server may already have committed.','After restart, a different account is active.','The row stays isolated and paused. Do not send it using the new account token.']};
 if(c.switchAccount&&!c.bound)return {local:true,queued:true,orders:'Unknown',status:'Unsafe: attempted replay under a different identity',safe:false,events:['The original operation belongs to account A.','Recovery sends the row using account B’s credentials.','This violates identity isolation. Exact server effect depends on authorization; the model flags unsafe replay.']};
 const safe=c.stable&&c.dedupe;
 return {local:true,queued:false,orders:safe?1:2,status:safe?'Recovered: one order, authoritative outcome reconciled':'Unsafe replay: a duplicate order in this model',safe,events:['Local change and outbox are durable.','Server commits; process dies before durable acknowledgement.',`Recovery ${c.stable?'uses the persisted operation key':'generates a different key'}.`,safe?'Server deduplicates and returns the original outcome; local state is reconciled.':'The duplicate is not recognized; replay creates another business effect.']};
}
function simTrace(c){const cases={a:{outside:1500,server:120,db:50,app:80,cause:'outside'},b:{outside:120,server:1420,db:1250,app:80,cause:'database'},c:{outside:120,server:120,db:50,app:1400,cause:'app'}};const x=cases[c.scenario];return {...x,total:x.outside+x.server+x.app,http:x.outside+x.server};}
function simMetrics(c){const operations=100,failed=c.fail,recovered=Math.round(failed*c.recover/100),attempts=100+failed,success=100-failed+recovered;return {operations,failed,recovered,attempts,success,opRate:success,attemptRate:success/attempts*100,budget:operations*.005};}
function labBody(id){
 const c=config(id);const run=ui.labRuns[id];let controls='',intro='',goal='';
 if(id==='http'){intro='These are controlled response examples. A status code narrows the decision, but the endpoint contract and operation semantics still matter.';goal='Correctly handle 202, 204, and 429. Run each scenario with the right action.';controls=selectControl(id,'status','Response',Object.entries(HTTP_CASES).map(([v,x])=>[v,`${v} ${x.name}`]))+selectControl(id,'action','Your next action',[['render','Validate JSON and render the result'],['pending','Track accepted work as pending'],['empty','Handle an explicitly empty response'],['refresh','Join a bounded token refresh'],['forbidden','Show a permission refusal'],['conflict','Resolve a version conflict'],['wait','Respect Retry-After / remaining budget'],['retry','Bounded retry of this safe read']]);}
 if(id==='retry'){intro='The server commits the first order, then its reply disappears. A retry can either recover that result or create another order. Times are illustrative; “jitter” uses a fixed 180 ms sample so the simulation is repeatable.';goal='Recover the order within the budget with exactly one server-side order. Use a stable key and modeled durable server deduplication.';controls=rangeControl(id,'attempts','Maximum total attempts',1,4)+rangeControl(id,'budget','Overall budget',1000,6000,250,' ms')+checkControl(id,'stable','Reuse the persisted operation key')+checkControl(id,'dedupe','Server implements atomic durable deduplication')+checkControl(id,'jitter','Use a sampled backoff with jitter');}
 if(id==='cache'){intro='A catalog was cached by account A. This model simulates mounting a consumer now. Inactivity is capped at the cache age. It models query-cache policy only, not a native HTTP cache.';goal='First show useful stale data while a refresh starts. Then switch to account B with an account-scoped key, so A’s data cannot be reused.';controls=rangeControl(id,'age','Age since successful fetch',0,180,5,' s')+rangeControl(id,'stale','staleTime',0,120,5,' s')+rangeControl(id,'inactive','Time without an observer',0,180,5,' s')+rangeControl(id,'gc','gcTime',10,240,10,' s')+checkControl(id,'switchAccount','Mount as account B instead of A')+checkControl(id,'scope','Include account identity in the query key');}
 if(id==='auth'){intro='Every concurrent request used the same expired access token. In this simplified provider model, one use of the rotating refresh token succeeds and duplicate uses are rejected. Real provider revocation/reuse policy can differ.';goal='Enable one shared refresh, log out while it runs, and prevent the late response from restoring a session.';controls=rangeControl(id,'calls','Concurrent expired requests',2,8)+checkControl(id,'single','Single-flight refresh per session')+checkControl(id,'logout','User logs out before refresh completes')+checkControl(id,'guard','Check the captured session epoch before saving/replaying');}
 if(id==='outbox'){intro='Interrupt a durable write and inspect restart behavior. This is a state-machine model, not a database or server implementation. Authorization and idempotency behavior still need real integration tests.';goal='Recover from a crash after server commit with one effect, using atomic local intent, a stable key, server deduplication, and account ownership checks.';controls=selectControl(id,'crash','Crash point',[['local','Between local change and outbox insert'],['server','After server commit, before response'],['ack','After response, before durable local acknowledgement']])+checkControl(id,'atomic','Save local change + outbox in one transaction')+checkControl(id,'stable','Persist and reuse the same operation key')+checkControl(id,'dedupe','Server durably deduplicates the key')+checkControl(id,'switchAccount','Restart with a different active account')+checkControl(id,'bound','Bind the outbox to its original account');}
 if(id==='trace'){intro='Explore three fabricated traces with known model timings. “Outside the server span” does not identify DNS, TLS, transit, or queueing by itself. The bars show timing relationships, not precise native phase instrumentation.';goal='Choose the region dominating the selected scenario, with compatible propagation and server sampling enabled. Also try disabling each to understand a gap.';controls=selectControl(id,'scenario','Controlled scenario',[['a','Scenario A'],['b','Scenario B'],['c','Scenario C']])+selectControl(id,'cause','Your diagnosis',[['unknown','Choose the dominant region…'],['outside','Time outside the server span'],['database','Backend database work'],['app','App processing after HTTP']])+checkControl(id,'propagate','Compatible context propagation across app and API')+checkControl(id,'sampled','Retain the server spans in this sampled trace');}
 if(id==='metrics'){intro='100 eligible user operations each make one initial request. Each initial failure gets exactly one retry. Every success event below represents a successful attempt; cache hits and cancellations are excluded from this particular model.';goal='Recover every initial failure, then use user operations as the denominator for final user-operation success. Notice that attempt success still differs.';controls=rangeControl(id,'fail','Initial failures out of 100',0,50)+rangeControl(id,'recover','Failures recovered by the retry',0,100,5,'%')+selectControl(id,'denominator','Denominator for final user-operation success',[['attempts','All HTTP attempts'],['operations','All eligible user operations'],['successes','Only successful events']]);}
 if(id==='diagnosis'){const d=DIAGNOSES[Number(c.case)];intro='Read the evidence before choosing a cause. Then choose the next action that addresses that layer without hiding or amplifying the problem.';goal='Solve at least three different cases with both the cause and next step correct.';controls=selectControl(id,'case','Incident',DIAGNOSES.map((d,i)=>[String(i),d.title]))+selectControl(id,'cause','Most supported explanation',[['','Choose a cause…'],...d.causes.map((s,i)=>[String(i),s])])+selectControl(id,'step','Next action',[['','Choose a next action…'],...d.steps.map((s,i)=>[String(i),s])]);}
 return `<div class="callout">${intro}</div><section class="panel"><div class="eyebrow">Your challenge</div><p style="font-size:.88rem">${goal}</p><div class="lab-controls">${controls}</div>${btn(id==='diagnosis'?'Check the evidence':'Run the simulation →','run-lab',`data-id="${id}"`,'primary')}</section>${id==='http'?`<div class="code-wrap"><span class="code-lang">Controlled response</span><pre><code>HTTP ${c.status} ${HTTP_CASES[c.status].name}\n${escape(HTTP_CASES[c.status].body)}</code></pre></div>`:''}${id==='diagnosis'?`<section class="panel"><h3>Evidence available</h3>${events(DIAGNOSES[Number(c.case)].evidence)}</section>`:''}<div class="lab-output" aria-live="polite">${run?.output||'<p class="muted">Change the controls, predict the result, then run the model.</p>'}</div><div class="actions">${linkBtn('Read the related chapter →',`lesson/${labById[id].lesson}`,'ghost')}${linkBtn('All labs','labs','ghost')}</div>`;
}
function labIndex(){return `<div class="chapter-head"><div class="eyebrow">A safe place to break things</div><h1>Predict. Change. Observe.</h1><p class="subtitle">Eight browser simulations that make invisible networking behavior visible.</p></div><p class="muted">Every lab includes a challenge and an explanation. Badges save locally. These models do not make real API calls, execute React Native code, or prove a production guarantee.</p><div class="lab-grid">${LABS.map(l=>`<button class="lab-card" data-action="nav" data-route="labs/${l.id}"><span class="lab-icon" aria-hidden="true">${l.icon}</span><h3>${l.title}</h3><p>${l.desc}</p><span class="badge">${state.labs[l.id]?'✓ Challenge completed':'Open the lab →'}</span></button>`).join('')}</div>`;}
function labs(id){if(!id)return labIndex();const l=labById[id];return `<div class="chapter-head"><div class="eyebrow">Interactive lab · ${LABS.indexOf(l)+1} / 8</div><h1>${l.title}</h1><p class="subtitle">${l.desc}</p>${state.labs[id]?'<span class="badge">✓ Challenge completed · saved locally</span>':''}</div>${labBody(id)}`;}
function runLab(id){const c=config(id);const old=ui.labRuns[id]||{};let output='',pass=false,seen=old.seen||[];
 if(id==='http'){const x=HTTP_CASES[c.status],correct=x.action===c.action;if(correct&&!seen.includes(c.status))seen.push(c.status);pass=['202','204','429'].every(s=>seen.includes(s));output=`<div class="result-banner"><h3>${correct?'Good decision.':'Reconsider the response contract.'}</h3><p>${x.explain}</p><small>Challenge scenarios understood: ${['202','204','429'].filter(s=>seen.includes(s)).join(', ')||'none yet'}.</small></div>`;}
 if(id==='retry'){const x=simRetry(c);pass=x.safe&&c.jitter;output=readouts([[x.attempts,'HTTP attempts'],[x.orders,'server orders'],[x.elapsed+' ms','modeled elapsed time']])+events(x.timeline.map((t,i)=>[t,i===x.timeline.length-1?(x.safe?'good':'bad'):'']))+`<div class="callout ${x.safe?'':'warning'}">${x.safe?'The second attempt recovered one logical operation. The stable key and the modeled server contract worked together.':x.orders>1?'A retry became another business operation. A disabled button or a random new key would not prevent this.':'The model has no confirmed client outcome yet. Reconcile later rather than claiming the order failed.'} The maximum-attempt setting is a cap; a successful recovery stops early.</div>`;}
 if(id==='cache'){const x=simCache(c);if(x.usable&&x.stale&&!x.leak&&!seen.includes('stale'))seen.push('stale');if(c.switchAccount&&c.scope&&!x.usable&&!seen.includes('isolation'))seen.push('isolation');pass=seen.includes('stale')&&seen.includes('isolation');output=readouts([[x.present?'Retained':'Collected','old cache entry'],[x.usable?'Available':'Not reusable','data for this identity'],[x.fetch?'Start read':'No stale-driven read','on this modeled mount']])+events([[`The entry is ${c.age} s old; staleTime is ${c.stale} s. It is ${x.stale?'stale':'fresh'}.`,''],[`Effective inactivity is ${x.inactive} s; gcTime is ${c.gc} s. ${x.present?'The old entry remains.':'It is eligible for collection in this model.'}`,''],[x.leak?'Privacy bug: account B reused account A’s data under a shared key.':c.switchAccount?'The account-scoped key has no result for B; fetch B’s data.':x.usable&&x.stale?'Show useful stale data while the mount triggers refresh.':'Use the configured identity and freshness policy.',x.leak?'bad':'good']])+`<p class="micro">Challenge: stale data ${seen.includes('stale')?'✓':'○'} · account isolation ${seen.includes('isolation')?'✓':'○'}. Becoming stale alone is not modeled as a timer-triggered fetch.</p>`;}
 if(id==='auth'){const x=simAuth(c);pass=c.single&&c.logout&&c.guard;output=readouts([[x.refreshes,'refresh requests'],[x.rejections,'modeled duplicate rejections'],[x.active?'Active':'Signed out','session after completion']])+events([`${c.calls} API requests receive the documented expired-token response.`,c.single?'They share one in-flight refresh owned by the current session.':'Each starts a refresh using the same rotating credential.',...(c.logout?[['Logout increments the session generation.',''],[c.guard?'The late refresh response is rejected; no tokens are saved or old requests replayed.':'The late response saves credentials and resurrects the session: a race.',c.guard?'good':'bad']]:['The accepted refresh result updates the active session.'])])+`<div class="callout">Single-flight prevents this modeled refresh stampede. The epoch check solves a different problem: stale-session results arriving after logout. Real provider rotation/reuse semantics must also be verified.</div>`;}
 if(id==='outbox'){const x=simOutbox(c);pass=c.crash!=='local'&&!c.switchAccount&&c.atomic&&c.stable&&c.dedupe&&c.bound;output=readouts([[x.orders,'modeled server effects'],[x.local?'Yes':'No','local change durable'],[x.queued?'Paused/pending':'No pending row','outbox after recovery']])+`<h3>${escape(x.status)}</h3>`+events(x.events.map((s,i)=>[s,i===x.events.length-1?(x.safe?'good':'bad'):'']))+`<div class="callout">A durable outbox records intent. Stable identity plus server deduplication handles repeated attempts; account binding prevents cross-user replay. The local transaction must actually be atomic in your chosen database.</div>`;}
 if(id==='trace'){const x=simTrace(c);pass=c.cause===x.cause&&c.propagate&&c.sampled;const row=(label,start,duration,type)=>`<div class="span-row"><span>${label}<br><small>${duration} ms</small></span><div class="span-track"><span class="span-bar ${type}" style="left:${start/x.total*100}%;width:${duration/x.total*100}%"></span></div></div>`;const serverStart=Math.round(x.outside/2);output=readouts([[x.total+' ms','intent → useful content'],[x.http+' ms','HTTP attempt'],[x.app+' ms','app processing']])+`<div class="waterfall" aria-label="Modeled span durations">${row('catalog.load',0,x.total,'')}${row('HTTP client',0,x.http,'')}${c.sampled?row(c.propagate?'↳ API server':'API (other trace)',serverStart,x.server,'server')+row('↳ database',serverStart+20,x.db,'db'):''}${row('decode / render',x.http,x.app,'app')}<div class="trace-axis"><span>0 ms</span><span>${x.total} ms</span></div></div><div class="callout ${pass?'':'warning'}">${c.cause==='unknown'?'Choose a region using the evidence.':c.cause===x.cause?'Your diagnosis matches the modeled dominant region.':'The bars point to a different dominant region.'} ${!c.propagate?'The API spans belong to a separate trace: fix compatible propagation and parent extraction.':!c.sampled?'The API processed the call, but its spans are not retained here. Absence does not prove non-receipt.':`The connected trace shows ${x.cause==='outside'?'substantial client time outside the server span; it does not identify the exact network phase':x.cause==='database'?'database work dominating the server path':'post-HTTP app processing dominating the user wait'}.`}</div>`;}
 if(id==='metrics'){const x=simMetrics(c);pass=c.fail>0&&c.recover===100&&c.denominator==='operations';const chosen=c.denominator==='operations'?x.opRate:c.denominator==='attempts'?x.attemptRate:100;output=readouts([[x.opRate.toFixed(1)+'%','operation success'],[x.attemptRate.toFixed(1)+'%','attempt success'],[x.attempts,'total attempts']])+events([`${x.operations} operations → ${x.failed} initial failures → ${x.recovered} recovered by one retry.`,`${x.success} successful operations / 100 eligible operations = ${x.opRate.toFixed(1)}%.`,`${x.success} successful attempts / ${x.attempts} attempts = ${x.attemptRate.toFixed(1)}%.`])+`<div class="callout ${c.denominator==='operations'?'':'warning'}">Your selected denominator reports ${chosen.toFixed(1)}%. ${c.denominator==='operations'?'This answers the final user-operation success question.':c.denominator==='attempts'?'That is an attempt metric, which answers a different question.':'Counting only success events hides every failure and is not a success-rate denominator.'} At an illustrative 99.5% objective, the budget over 100 operations is 0.5 bad operations mathematically; real alerting needs a suitable window and population.</div>`;}
 if(id==='diagnosis'){const x=DIAGNOSES[Number(c.case)],correct=c.cause===String(x.correctCause)&&c.step===String(x.correctStep);if(correct&&!seen.includes(c.case))seen.push(c.case);pass=seen.length>=3;output=`<div class="result-banner"><h3>${correct?'Evidence and action align.':'Revisit the layer and the next step.'}</h3><p>${escape(x.why)}</p><small>${seen.length}/3 different incidents solved for the challenge.</small></div>`;}
 ui.labRuns[id]={seen,output};markLab(id,pass);render();
}
function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportNotes(){let s='# React Native networking — field notes\n\n'+new Date().toISOString()+'\n\n';for(const l of DATA.lessons)if(state.notes[l.id]?.trim())s+=`## ${l.title}\n\n${state.notes[l.id]}\n\n`;s+='## Production evidence checklist\n\n'+DATA.checklist.map(([k,v],i)=>`- [${state.checklist[i]?'x':' '}] ${k}: ${v}`).join('\n')+'\n\n## Incident notebook\n\n';for(const [k,v]of Object.entries(state.journal))s+=`### ${k}\n\n${v}\n\n`;download('networking-field-notes.md',s,'text/markdown');}
function downloadCourse(){
 const css=document.getElementById('course-style').textContent,js=document.getElementById('course-script').textContent,data=document.getElementById('course-data').textContent;
 const closeScript='<'+'/script>';
 const html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>The Network Fieldguide · React Native</title><style id="course-style">'+css+'</style></head><body><a class="skip" href="#main-content">Skip to content</a><div id="app">Loading the fieldguide…</div><noscript>Enable JavaScript for the interactive course.</noscript><div id="toast" role="status" aria-live="polite"></div><input id="import-file" type="file" accept="application/json,.json" hidden><script type="application/json" id="course-data">'+data+closeScript+'<script id="course-script">'+js+closeScript+'</body></html>';
 download('react-native-networking-fieldguide.html',html,'text/html');toast('HTML saved. Export progress JSON separately to transfer your work.');
}
function render(){const [view,id]=route.split('/');const pages={home,lesson:()=>lesson(id),labs:()=>labs(id),review,notes,sources,glossary,exam};$('#app').innerHTML=shell((pages[view]||home)());updateSave();}
function redrawWithFocus(selector){const y=window.scrollY;render();if(selector)$(selector)?.focus({preventScroll:true});window.scrollTo({top:y,behavior:'instant'});}
document.addEventListener('click',async event=>{
 const b=event.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='nav'){nav(b.dataset.route);return;}
 if(a==='choice'){ui.drafts.set(b.dataset.q,Number(b.dataset.choice));redrawWithFocus(`[data-action="choice"][data-q="${b.dataset.q}"][data-choice="${b.dataset.choice}"]`);return;}
 if(a==='check-q'){const id=b.dataset.q,q=questions[id],choice=ui.drafts.get(id);if(!q||!Number.isInteger(choice)||choice<0)return;const prev=state.answers[id];const correct=choice===q.answer;state.answers[id]={choice,correct,mastered:!!prev?.mastered||correct,attempts:(prev?.attempts||0)+1,wrong:(prev?.wrong||0)+(correct?0:1),at:new Date().toISOString()};ui.drafts.delete(id);save();redrawWithFocus(`[data-action="retry-q"][data-q="${id}"]`);toast(correct?'Correct. Read the explanation to check your reasoning.':'Read the explanation, then try again when ready.');return;}
 if(a==='retry-q'){ui.drafts.set(b.dataset.q,-1);redrawWithFocus(`[data-action="choice"][data-q="${b.dataset.q}"]`);return;}
 if(a==='read'){state.read[b.dataset.id]=!state.read[b.dataset.id];save();redrawWithFocus(`[data-action="read"]`);return;}
 if(a==='bookmark'){state.bookmarks[b.dataset.id]=!state.bookmarks[b.dataset.id];save();redrawWithFocus('[data-action="bookmark"]');return;}
 if(a==='flip-card'){ui.flipped=!ui.flipped;redrawWithFocus('[data-action="flip-card"]');return;}
 if(a==='next-card'){ui.flashIndex=(ui.flashIndex+1)%Object.keys(DATA.glossary).length;ui.flipped=false;redrawWithFocus('[data-action="next-card"]');return;}
 if(a==='exam-choice'){ui.examDrafts[b.dataset.q]=Number(b.dataset.choice);redrawWithFocus(`[data-action="exam-choice"][data-q="${b.dataset.q}"][data-choice="${b.dataset.choice}"]`);return;}
 if(a==='submit-exam'){if(!DATA.exam.every(q=>Number.isInteger(ui.examDrafts[q.id])))return;const score=DATA.exam.filter(q=>ui.examDrafts[q.id]===q.answer).length;state.exam={responses:{...ui.examDrafts},score,bestScore:Math.max(state.exam.bestScore||0,score),submittedAt:new Date().toISOString()};save();render();window.scrollTo({top:0,behavior:'instant'});toast(`Assessment saved: ${score}/16.`);return;}
 if(a==='retake-exam'){state.exam={bestScore:state.exam.bestScore||0};ui.examDrafts={};save();render();return;}
 if(a==='run-lab'){runLab(b.dataset.id);return;}
 if(a==='copy-code'){const text=b.closest('.code-wrap').querySelector('code').textContent;try{await navigator.clipboard.writeText(text);toast('Code copied.');}catch{const range=document.createRange();range.selectNodeContents(b.closest('.code-wrap').querySelector('code'));const selection=getSelection();selection.removeAllRanges();selection.addRange(range);toast('Code selected. Use your browser’s Copy command.');}return;}
 if(a==='export-recovery'&&recoveryRaw!==null){download('rn-networking-unreadable-record.txt',recoveryRaw,'text/plain');toast('Original saved contents downloaded without modification.');return;}
 if(a==='export'){download('rn-networking-progress.json',JSON.stringify(state,null,2),'application/json');toast('Progress backup exported. Keep it somewhere you can find later.');return;}
 if(a==='import'){$('#import-file').value='';$('#import-file').click();return;}
 if(a==='confirm-import'&&pendingImport){state=pendingImport;pendingImport=null;storageLocked=false;recoveryRaw=null;ui.drafts.clear();ui.examDrafts={};save();render();toast('Backup imported. Current local progress was replaced.');return;}
 if(a==='cancel-import'){pendingImport=null;render();return;}
 if(a==='download-course'){downloadCourse();return;}
 if(a==='export-notes'){exportNotes();return;}
 if(a==='reset'){ui.confirmReset=true;render();return;}
 if(a==='cancel-reset'){ui.confirmReset=false;render();return;}
 if(a==='confirm-reset'){try{localStorage.removeItem(KEY);}catch{}state=empty();ui.drafts.clear();ui.examDrafts={};ui.labRuns={};ui.labConfig={};ui.confirmReset=false;storageLocked=false;recoveryRaw=null;save();render();toast('This course’s local progress was reset.');return;}
});
document.addEventListener('input',event=>{
 const t=event.target;
 if(t.id==='course-search'){ui.search=t.value;$('#course-results').innerHTML=overviewResults();return;}
 if(t.id==='source-search'){ui.sourceSearch=t.value;$('#source-results').innerHTML=sourcesResults();return;}
 if(t.id==='glossary-search'){ui.glossarySearch=t.value;$('#glossary-results').innerHTML=glossaryResults();return;}
 if(t.dataset.note){state.notes[t.dataset.note]=t.value;save();return;}
 if(t.dataset.journal){state.journal[t.dataset.journal]=t.value;save();return;}
 if(t.dataset.lab&&t.type==='range'){config(t.dataset.lab)[t.dataset.field]=Number(t.value);const label=t.closest('label').querySelector('strong');if(label){const old=label.textContent;label.textContent=t.value+(old.endsWith(' ms')?' ms':old.endsWith(' s')?' s':old.endsWith('%')?'%':'');}if(ui.labRuns[t.dataset.lab])ui.labRuns[t.dataset.lab].output='<p class="muted">Settings changed. Run again to compare the new result.</p>';$('.lab-output').innerHTML='<p class="muted">Settings changed. Run again to compare the new result.</p>';return;}
});
document.addEventListener('change',async event=>{
 const t=event.target;
 if(t.id==='chapter-picker'){nav(`lesson/${t.value}`);return;}
 if(t.dataset.check!==undefined){state.checklist[t.dataset.check]=t.checked;save();$('#check-count').textContent=`${Object.values(state.checklist).filter(Boolean).length}/${DATA.checklist.length} verified`;return;}
 if(t.dataset.lab&&t.type!=='range'){const id=t.dataset.lab,key=t.dataset.field;config(id)[key]=t.type==='checkbox'?t.checked:t.value;if(id==='diagnosis'&&key==='case'){config(id).cause='';config(id).step='';}if(ui.labRuns[id])ui.labRuns[id].output='<p class="muted">Settings changed. Run again to compare the new result.</p>';redrawWithFocus(`[data-lab="${id}"][data-field="${key}"]`);return;}
 if(t.id==='import-file'&&t.files?.length){const file=t.files[0];if(file.size>2*1024*1024){toast('Backup is too large. The limit is 2 MB.');return;}try{pendingImport=validateProgress(JSON.parse(await file.text()));route='notes';render();toast('Backup validated. Review it before replacing your progress.');}catch(error){toast('Could not import: '+error.message);}return;}
});
window.Fieldguide={data:DATA,getProgress:()=>JSON.parse(JSON.stringify(state)),validateProgress,models:{retry:simRetry,cache:simCache,auth:simAuth,outbox:simOutbox,trace:simTrace,metrics:simMetrics}};
render();
})();
